import{a as d}from"./chunk-IO4NLMGT-v7540.js";import{j as u}from"./chunk-LGF5RK5L-v8400.js";import{m as p}from"./chunk-2OB4V521-v8400.js";import{b as l,c as o,d as h,l as r}from"./chunk-4O7IN74N-v8400.js";import{d as e}from"./chunk-6K6QREZY-v8400.js";var f=a=>a?a.min<=-15?e("up to {n}",{n:a.max}):a.max>=40?e("{n} and over",{n:a.min}):a.min===a.max?`${a.min}`:e("{a} to {b}",{a:a.min,b:a.max}):e("water only"),m=(a,i,c)=>o`<div class="how-ladder"><h3>${a}</h3><div class="ladder__bar">${["A","B","C","D","E"].map(n=>o`<span class="ladder__seg g-${n} is-on"><b>${n}</b><small>${f(i.find(t=>t.grade===n))}</small></span>`)}</div><p class="small muted">${c}</p></div>`,s=a=>l(e(a));function F(a){document.title=`${e("How FoodScan decides")} · FoodScan`;let i=["A strictly higher Nutri-Score letter. If you’re at A, there is nothing higher and we say so.","A real, named improvement (for example less sugar or saturated fat, or more fibre). A higher letter with no real difference in the numbers is labelled “slightly higher grade”.","Trade-offs are shown, for example “but more salt”.","Never more processed (NOVA) than what you scanned, never a record with a data error, and never anything that conflicts with your allergens or diet.","The same kind of food only. Each product’s food family (bread, cheese, crackers, spreads…) is worked out from all of its categories, so one wrong tag can’t turn a bread into fish croquettes.","Closest matches first. A better yogurt is a better answer than a better biscuit.","Sold where you shop first. Your country comes from your phone (or your choice in Me), and every suggestion says whether it’s listed there.","Each suggestion is re-read by its exact barcode before it is marked “checked just now”, so a stale search result can’t slip through.","When nothing has a higher grade, products with the same grade and a real difference (less sugar, more fibre) are shown instead, and never called “better”."],c=["A calculated grade is shown only when every possible value of what is missing would give the same letter. Fibre, protein or fruit and vegetables not reported? Their points are treated as a range, never as zero.","Never for drinks, cheese, fats, oils, nuts, seeds or meat, which follow special rules, and never when the source itself says Nutri-Score does not apply (stock cubes, spices, tea).","A calculated grade is never used to suggest a better choice: those must carry a grade the source published.","The point tables are checked against real products graded by Open Food Facts: the points and the letter must match exactly."],n=[["Does the explanation add up?","The point-by-point reasons are shown only when the points sum to the totals and the totals give the reported score. If not, FoodScan says the working isn’t available rather than showing numbers that don’t reconcile."],["Are the numbers possible?","Sugars can’t exceed carbohydrate. A juice can’t contain 8 g of salt per 100 ml. When a record contradicts itself, the grade is put on hold and the suspect value is flagged. A real example: a 900 ml orange juice listed with 7.9 g of salt was getting a grade E purely because of that typing slip."],["Does the allergen list match the ingredients?","Community-entered allergen tags are often incomplete. FoodScan reads the ingredient text in several languages (for example Greek “σιμιγδάλι σκληρού σίτου”, durum wheat semolina) and flags anything the list missed. This check only ever adds warnings; it never clears one."],["Is it filed in the right category?","Better choices come from the same kind of product. If a record’s category contradicts its name (a spaghetti filed under “dairy substitutes”), FoodScan compares it with other pasta and tells you it did."]];return h(a,o`<div class="page prose"><p class="eyebrow">${r("shield",14)}${e("Method & sources")}</p><h1 class="page__title">${e("How FoodScan decides")}</h1>
    <p class="lead">${e("FoodScan’s promise is simple: show the grade the experts published, show why, and be honest about what we don’t know.")}</p>

    <section class="card"><h2>${e("The grade: Nutri-Score")}</h2>
      <p>${s("The A to E grade is the <b>Nutri-Score</b>, calculated by Open Food Facts with the official 2023 algorithm. It weighs what’s less favourable (energy, sugars, saturated fat, salt, sweeteners) against what’s favourable (fibre, protein, fruit, vegetables and legumes). Fewer points against means a better grade. It compares foods per 100 g, or per 100 ml for drinks.")}</p>
      ${m(e("Where a score lands: foods"),d.food,e("Total points: lower is better."))}${m(e("Where a score lands: drinks"),d.drink,e("Drinks are judged more strictly. Only water can score A."))}
      <p>${s("FoodScan never replaces this with its own number. Our checks run <em>around</em> the grade: when to show it, how to explain it, and when to hold it back.")}</p></section>

    <section class="card"><h2>${e("When the source has no grade")}</h2>
      <p>${s("Open Food Facts leaves a product ungraded when something it needs is missing, often only the category. When the label values that <em>are</em> there are enough, FoodScan applies the same official 2023 method itself and marks the result <b>calculated</b>: a dashed seal, the word “Calculated”, and the full working.")}</p>
      <ul class="ticks">${c.map(t=>o`<li>${r("check",15)}${e(t)}</li>`)}</ul></section>

    <section class="card"><h2>${e("What FoodScan checks on every product")}</h2>
      <ol class="checks">${n.map(([t,g])=>o`<li><h3>${e(t)}</h3><p>${e(g)}</p></li>`)}</ol></section>

    <section class="card"><h2>${e("Better choices: what “better” means")}</h2>
      <ul class="ticks">${i.map(t=>o`<li>${r("check",15)}${e(t)}</li>`)}</ul>
      <p class="small muted">${e("Suggestions come from up to 40 of the most popular products per category on Open Food Facts. That’s a sample, not every product in a shop, and “listed in” describes the database, not today’s shelf or price.")}</p></section>

    <section class="card"><h2>${e("Other scales you’ll see")}</h2>
      <p>${s("<b>NOVA</b> describes how processed a food is, from 1 to 4. It’s separate from the grade and shown as reported.")}</p>
      <ul class="nova-list">${[1,2,3,4].map(t=>o`<li><i class="chip chip--nova n-${t}"><b>${t}</b></i><span>${p[t].line}</span></li>`)}</ul>
      <p>${s("<b>Low, medium and high</b> bars use the UK front-of-pack colour guide thresholds per 100 g or 100 ml. They describe amounts, and they’re not a second grade.")}</p>
      <p>${s("<b>Percent of daily reference</b> uses the EU labelling reference intakes for an average adult: 2,000 kcal, 90 g total sugars, 20 g saturated fat and 6 g salt. They’re conventions for labels, not advice for you.")}</p>
      <p>${s("<b>Sugar cubes</b> count 4 g of sugar per cube, a picture, not a measure of harm.")}</p></section>

    <section class="card"><h2>${e("Where the data comes from, and its limits")}</h2>
      <p>${e("Product data comes from Open Food Facts, an open database built by contributors worldwide, available under the Open Database Licence. It isn’t laboratory-verified and some records are incomplete or out of date: formulas change, and photos can lag behind packs.")} <a class="link" href="https://world.openfoodfacts.org" target="_blank" rel="noopener noreferrer">openfoodfacts.org ${r("external",13)}</a></p>
      <p>${e("That’s why every report shows when the record was last edited, how it was checked, and a link to fix it. FoodScan is a tool for comparing foods, not medical or dietary advice. If you have a food allergy, always read the pack.")}</p></section>

    ${u()}
    <section class="card"><h2>${e("Privacy")}</h2><p>${e("No accounts, no ads, no personal tracking. Your history, saved foods, daily log and rules are stored only on your device. Looking up a barcode or searching sends that barcode or search text to our server and Open Food Facts to fetch the answer, and nothing that identifies you.")}</p>
      <p>${e("FoodScan counts anonymous events, such as “a scan found a product”. A shared link carries a random share token, made fresh for each share, so we can count how many shared links lead to a scan; it is not linked to you, your device or your foods. Browsers that ask not to be tracked send nothing.")}</p></section>
    <p class="center"><a class="btn btn--primary" href="#/demo">${r("play",18)}${e("See it in action")}</a></p></div>`),()=>{}}export{F as renderHow};
